// InvoiceServiceServer is the server API for InvoiceService service.
// All implementations must embed UnimplementedInvoiceServiceServer
// for forward compatibility.
//
// Invoice Service — 電子發票（58 號詳細設計書）
//
// 通用 issuer→recipient 模型：issuer ∈ {賣家, 平台}；recipient ∈ {買家, 賣家, 外部對象}；
// 觸發 ∈ {訂單付款自動, ADM 手動}；品項來源 ∈ {訂單快照, ADM 手填}。
// Phase 1 只實作「賣家→買家」自動線 ＋ ADM 手動開票，其餘由模型容納但不接觸發器。
//
// 約定（全檔適用，不逐 message 重複）：
//   - 每個 Response 的欄位 1/2 恆為 int32 code = 1; string message = 2;
//     （Gateway EnvelopeGuardInterceptor 靠 GetCode 判定業務錯誤，漏了會靜默當成功）
//   - 所有數字（ID/金額/數量/計數/版本/頁碼）一律 string；
//     例外僅 Request 內由 Gateway 注入的身分欄位（buyer_id / store_id / actor_account_id）用 int64
//   - 所有時間一律 string，ISO 8601 UTC 秒精度（YYYY-MM-DDTHH:mm:ssZ）
//   - 狀態/類型碼一律 string，值域見 docs/代碼管理（CodeMeta）/{業務狀態碼,業務類型碼,內部技術碼}.md
//   - 金額單位「元」的整數字串，禁止 double/decimal
//   - 本服務不 import common/delegation.proto：發票是 ADM 代行禁區（56 §6.1.1）
type InvoiceServiceServer interface {
	// 常用發票資料（B08）
	ListBuyerInvoiceProfiles(context.Context, *ListBuyerInvoiceProfilesRequest) (*ListBuyerInvoiceProfilesResponse, error)
	CreateBuyerInvoiceProfile(context.Context, *CreateBuyerInvoiceProfileRequest) (*BuyerInvoiceProfileResponse, error)
	UpdateBuyerInvoiceProfile(context.Context, *UpdateBuyerInvoiceProfileRequest) (*BuyerInvoiceProfileResponse, error)
	DeleteBuyerInvoiceProfile(context.Context, *DeleteBuyerInvoiceProfileRequest) (*DeleteBuyerInvoiceProfileResponse, error)
	SetDefaultBuyerInvoiceProfile(context.Context, *SetDefaultBuyerInvoiceProfileRequest) (*BuyerInvoiceProfileResponse, error)
	// 訂單發票（B04/B05）
	GetOrderInvoice(context.Context, *GetOrderInvoiceRequest) (*GetOrderInvoiceResponse, error)
	GetInvoiceDocument(context.Context, *GetInvoiceDocumentRequest) (*GetInvoiceDocumentResponse, error)
	GetInvoiceDocumentFile(context.Context, *GetInvoiceDocumentFileRequest) (*GetInvoiceDocumentFileResponse, error)
	// 買家發票中心（B09，端點 68–69）：跨訂單的文件列表 ＋ document-scoped 詳情。
	// 這兩支與上面 order-scoped 的 GetOrderInvoice／GetInvoiceDocument 並存而非取代：
	// §2.3 方向三（平台→買家）的發票不掛在任何訂單底下，order-scoped 的入口取不到它。
	// 授權述詞是 recipient_type='BUYER' AND recipient_ref_id=當前買家（58A B09「權限與邊界」）
	// ⇒ 只會回自己是買受人的文件，前端不得再自行過濾。
	ListBuyerInvoiceDocuments(context.Context, *ListBuyerInvoiceDocumentsRequest) (*ListBuyerInvoiceDocumentsResponse, error)
	// 回既有的 GetInvoiceDocumentResponse（data 同為 InvoiceDocumentDetail）：符合 §6.2.2 決定 2
	// 的三個共用條件——payload 型別完全相同、語意是「同一份文件的另一種取得方式」、同屬買家角色面。
	GetBuyerInvoiceDocument(context.Context, *GetBuyerInvoiceDocumentRequest) (*GetInvoiceDocumentResponse, error)
	// 付款後修改（B06）
	CreateInvoiceCorrection(context.Context, *CreateInvoiceCorrectionRequest) (*InvoiceCorrectionResponse, error)
	GetInvoiceCorrection(context.Context, *GetInvoiceCorrectionRequest) (*InvoiceCorrectionResponse, error)
	// 未收到發票申訴（B07）
	CreateInvoiceComplaint(context.Context, *CreateInvoiceComplaintRequest) (*InvoiceComplaintResponse, error)
	ListOrderInvoiceComplaints(context.Context, *ListOrderInvoiceComplaintsRequest) (*ListInvoiceComplaintsResponse, error)
	GetInvoiceComplaint(context.Context, *GetInvoiceComplaintRequest) (*InvoiceComplaintResponse, error)
	// 買家在申訴流程中的三個動作（§7.3.5 K07／K11／K13）。三支都回**轉移後**的單筆，
	// 前端不必再打一次 GetInvoiceComplaint。K06 的主動半條（買家確認結案）Phase 1 不做，
	// 見 §6.1.6「為什麼是三支而不是四支」——不要看到 FSM 有四條就自己補第四支 RPC。
	RejectInvoiceComplaintResponse(context.Context, *RejectInvoiceComplaintResponseRequest) (*InvoiceComplaintResponse, error)
	WithdrawInvoiceComplaint(context.Context, *WithdrawInvoiceComplaintRequest) (*InvoiceComplaintResponse, error)
	ReopenInvoiceComplaint(context.Context, *ReopenInvoiceComplaintRequest) (*InvoiceComplaintResponse, error)
	GetSellerInvoiceOverview(context.Context, *GetSellerInvoiceOverviewRequest) (*GetSellerInvoiceOverviewResponse, error)
	// 稅務身分（S02）與自行開票責任條款（S04）
	GetSellerTaxProfile(context.Context, *GetSellerTaxProfileRequest) (*SellerTaxProfileResponse, error)
	SaveSellerTaxProfileDraft(context.Context, *SaveSellerTaxProfileDraftRequest) (*SellerTaxProfileResponse, error)
	SubmitSellerTaxProfile(context.Context, *SubmitSellerTaxProfileRequest) (*SellerTaxProfileResponse, error)
	RequestSellerTaxExtension(context.Context, *RequestSellerTaxExtensionRequest) (*SellerTaxProfileResponse, error)
	GetSelfIssueAttestation(context.Context, *GetSelfIssueAttestationRequest) (*SelfIssueAttestationResponse, error)
	AcceptSelfIssueAttestation(context.Context, *AcceptSelfIssueAttestationRequest) (*SelfIssueAttestationResponse, error)
	// AMEGO 憑證與啟用切點（S03）
	GetSellerProviderAccount(context.Context, *GetSellerProviderAccountRequest) (*SellerProviderAccountResponse, error)
	PutSellerProviderCredentials(context.Context, *PutSellerProviderCredentialsRequest) (*SellerProviderAccountResponse, error)
	VerifySellerProviderAccount(context.Context, *VerifySellerProviderAccountRequest) (*SellerProviderAccountResponse, error)
	ActivateSellerProviderAccount(context.Context, *ActivateSellerProviderAccountRequest) (*SellerProviderAccountResponse, error)
	RotateSellerProviderCredentials(context.Context, *RotateSellerProviderCredentialsRequest) (*SellerProviderAccountResponse, error)
	// 免用統一發票與收據授權（S05）
	GetSellerReceiptAuthorization(context.Context, *GetSellerReceiptAuthorizationRequest) (*SellerReceiptAuthorizationResponse, error)
	ConfirmSellerReceiptAuthorization(context.Context, *ConfirmSellerReceiptAuthorizationRequest) (*SellerReceiptAuthorizationResponse, error)
	// 發票紀錄與異常（S06/S07/S08）
	ListSellerInvoiceDocuments(context.Context, *ListSellerInvoiceDocumentsRequest) (*ListSellerInvoiceDocumentsResponse, error)
	GetSellerInvoiceDocument(context.Context, *GetSellerInvoiceDocumentRequest) (*GetSellerInvoiceDocumentResponse, error)
	// S12 進項分頁（端點 72）：recipient-scoped，與上面 issuer-scoped 的銷項是兩個資料集。
	// 不能靠同一支 RPC 加 flag 分流——銷項可作廢可折讓、進項是唯讀報稅憑證，法律角色不同。
	// 停權賣家仍可讀（進項憑證是賣家的財產，與能否營業無關，58A S12「權限」）。
	ListSellerReceivedInvoiceDocuments(context.Context, *ListSellerReceivedInvoiceDocumentsRequest) (*ListSellerReceivedInvoiceDocumentsResponse, error)
	ResendInvoiceNotification(context.Context, *ResendInvoiceNotificationRequest) (*ResendInvoiceNotificationResponse, error)
	// 端點 71（買家 B05 重寄）。**與賣家版分成兩支是 §5.1 角色分離的硬要求**，
	//
	//	不是重複：兩者的擁有者述詞不同（賣家用 store_id、買家用 buyer_id），
	//	而 §8.1.4 的 Tier A 要求「越權與不存在不可區分」＝ 擁有者必須進 WHERE。
	//	共用一支 request 的話 Gateway 送不出買家身分，服務端只剩兩條路：
	//	全部拒絕（端點死掉），或忽略擁有者（任何已登入買家可對任意 document_id
	//	觸發重寄 ＝ IDOR）。ADM 版早就分開了（ResendInvoiceNotificationForAdmin），
	//	買家版漏掉純粹是遺漏。
	//	Response 共用是允許的（§6.2.2 決定 2：payload 形狀完全相同）。
	ResendBuyerInvoiceNotification(context.Context, *ResendBuyerInvoiceNotificationRequest) (*ResendInvoiceNotificationResponse, error)
	GetSellerInvoiceJob(context.Context, *GetSellerInvoiceJobRequest) (*GetSellerInvoiceJobResponse, error)
	// 子路由 62R：端點 62 的前置讀取（order-scoped）。停權賣家唯一取得 job_id / version / can_report_external 的路徑
	ListOrderExternalIssuances(context.Context, *ListOrderExternalIssuancesRequest) (*ListOrderExternalIssuancesResponse, error)
	// 端點 62：A4 受控人工出口的最後一步，RESOLVED_EXTERNALLY 的唯一入口（§7 J30）
	ReportExternalIssuance(context.Context, *ReportExternalIssuanceRequest) (*GetSellerInvoiceJobResponse, error)
	// 買家申訴（S09/S10）
	ListSellerInvoiceComplaints(context.Context, *ListSellerInvoiceComplaintsRequest) (*ListInvoiceComplaintsResponse, error)
	GetSellerInvoiceComplaint(context.Context, *GetSellerInvoiceComplaintRequest) (*InvoiceComplaintResponse, error)
	RespondSellerInvoiceComplaint(context.Context, *RespondSellerInvoiceComplaintRequest) (*InvoiceComplaintResponse, error)
	GetInvoiceOverviewForAdmin(context.Context, *GetInvoiceOverviewForAdminRequest) (*GetInvoiceOverviewForAdminResponse, error)
	// 稅務身分審核（A02/A03）
	ListTaxReviewsForAdmin(context.Context, *ListTaxReviewsForAdminRequest) (*ListTaxReviewsForAdminResponse, error)
	GetTaxReviewForAdmin(context.Context, *GetTaxReviewForAdminRequest) (*GetTaxReviewForAdminResponse, error)
	DecideTaxReviewForAdmin(context.Context, *DecideTaxReviewForAdminRequest) (*DecideTaxReviewForAdminResponse, error)
	DecideTaxExtensionForAdmin(context.Context, *DecideTaxExtensionForAdminRequest) (*DecideTaxReviewForAdminResponse, error)
	// AMEGO 串接監控（A04/A09）
	ListProviderAccountsForAdmin(context.Context, *ListProviderAccountsForAdminRequest) (*ListProviderAccountsForAdminResponse, error)
	GetProviderAccountForAdmin(context.Context, *GetProviderAccountForAdminRequest) (*GetProviderAccountForAdminResponse, error)
	HealthCheckProviderAccountForAdmin(context.Context, *HealthCheckProviderAccountForAdminRequest) (*GetProviderAccountForAdminResponse, error)
	DeactivateProviderAccountForAdmin(context.Context, *DeactivateProviderAccountForAdminRequest) (*DeactivateProviderAccountForAdminResponse, error)
	ReactivateProviderAccountForAdmin(context.Context, *ReactivateProviderAccountForAdminRequest) (*GetProviderAccountForAdminResponse, error)
	RevokeProviderAccountForAdmin(context.Context, *RevokeProviderAccountForAdminRequest) (*RevokeProviderAccountForAdminResponse, error)
	ListProviderCutoversForAdmin(context.Context, *ListProviderCutoversForAdminRequest) (*ListProviderCutoversForAdminResponse, error)
	// 發票與工作佇列（A05/A06）
	ListInvoiceDocumentsForAdmin(context.Context, *ListInvoiceDocumentsForAdminRequest) (*ListInvoiceDocumentsForAdminResponse, error)
	GetInvoiceDocumentForAdmin(context.Context, *GetInvoiceDocumentForAdminRequest) (*GetInvoiceDocumentForAdminResponse, error)
	ResendInvoiceNotificationForAdmin(context.Context, *ResendInvoiceNotificationForAdminRequest) (*ResendInvoiceNotificationResponse, error)
	ListInvoiceJobsForAdmin(context.Context, *ListInvoiceJobsForAdminRequest) (*ListInvoiceJobsForAdminResponse, error)
	GetInvoiceJobForAdmin(context.Context, *GetInvoiceJobForAdminRequest) (*GetInvoiceJobForAdminResponse, error)
	RetryInvoiceJobForAdmin(context.Context, *RetryInvoiceJobForAdminRequest) (*InvoiceJobMutationResponse, error)
	CancelInvoiceJobForAdmin(context.Context, *CancelInvoiceJobForAdminRequest) (*InvoiceJobMutationResponse, error)
	// 端點 73：把停在人工出口、而且**沒有任何 operation** 的文件送回自動線。
	//
	// 🔴 端點 52 以 job_id 為鍵，而自動線落 AWAITING_MANUAL 時 operation 根本不建
	// （§7.1.3 的 AM 節點明文）⇒ 那些文件沒有 job_id，端點 52／53／56 全部組不出請求。
	// 本 RPC 是它們唯一的入口：ResumeFromManual（M1）＋ 補建那件缺席的 ISSUE operation。
	ResumeInvoiceDocumentForAdmin(context.Context, *ResumeInvoiceDocumentForAdminRequest) (*InvoiceJobMutationResponse, error)
	// 受控人工出口（決策 A4：查證 → 雙人確認 → 解鎖 → 回報）
	RequestManualUnlockForAdmin(context.Context, *RequestManualUnlockForAdminRequest) (*ManualUnlockResponse, error)
	ApproveManualUnlockForAdmin(context.Context, *ApproveManualUnlockForAdminRequest) (*ManualUnlockResponse, error)
	ReportManualResultForAdmin(context.Context, *ReportManualResultForAdminRequest) (*InvoiceJobMutationResponse, error)
	// 手動開票（通用 issuer→recipient）
	CreateManualIssuanceForAdmin(context.Context, *CreateManualIssuanceForAdminRequest) (*CreateManualIssuanceForAdminResponse, error)
	// 申訴（A07/A08）與稽核（A10）
	ListInvoiceComplaintsForAdmin(context.Context, *ListInvoiceComplaintsForAdminRequest) (*ListInvoiceComplaintsResponse, error)
	GetInvoiceComplaintForAdmin(context.Context, *GetInvoiceComplaintForAdminRequest) (*InvoiceComplaintResponse, error)
	ActOnInvoiceComplaintForAdmin(context.Context, *ActOnInvoiceComplaintForAdminRequest) (*ActOnInvoiceComplaintForAdminResponse, error)
	ListInvoiceAuditLogsForAdmin(context.Context, *ListInvoiceAuditLogsForAdminRequest) (*ListInvoiceAuditLogsForAdminResponse, error)
	// order-service 在 checkout preview 呼叫：解析該賣家對這一筆訂單的開票模式、
	// 金額拆解、法定告知與待審接單上限。這支決定 B01 能不能讓買家付款。
	ResolveOrderInvoiceModeInternal(context.Context, *ResolveOrderInvoiceModeInternalRequest) (*ResolveOrderInvoiceModeInternalResponse, error)
	// order-service 在 checkout confirm 呼叫：驗證買家發票輸入（載具/統編/捐贈碼格式與
	// 三者互斥）＋ 檢查待審接單上限，回傳可持久化的發票快照。
	ValidateOrderInvoiceInputInternal(context.Context, *ValidateOrderInvoiceInputInternalRequest) (*ValidateOrderInvoiceInputInternalResponse, error)
	// seller 模組與 ADM 查賣家是否已具備開票能力（薄查詢，供其他服務判斷）。
	GetSellerInvoiceCapabilitySimple(context.Context, *GetSellerInvoiceCapabilitySimpleRequest) (*GetSellerInvoiceCapabilitySimpleResponse, error)
	mustEmbedUnimplementedInvoiceServiceServer()
}

